// Author: MiYu. Development integration driver for real AI sources, private globals and live paid orders.
#include "session.h"
#include "setup.h"
#include <iostream>
using namespace war3;
int wmain(int argc,wchar_t** argv){try{if(argc<3 || argc>5)throw std::runtime_error("Usage: war3_ai_tests <data-root> <map> [race 0..3] [seconds 1..60]");unsigned race=argc>3?unsigned(std::stoi(argv[3])):0;double duration=argc>4?std::stod(argv[4]):2;if(race>3 || duration<=0 || duration>60)throw std::runtime_error("Invalid integration arguments");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());if(!setup.control(1,SlotControl::ComputerNormal) || !setup.race(1,race+1))throw std::runtime_error("Unable to set integration race");session.applySetup(setup);session.startMain();if(!session.ais()[1])throw std::runtime_error("Original map main did not start computer AI");session.advance(duration);auto& ai=*session.ais()[1];unsigned orders=0,queues=0,gathering=0,builds=0;for(auto& [id,u]:session.units())if(u->owner==1){orders+=u->currentOrder!=0;queues+=unsigned(u->production.size());gathering+=u->gather.phase!=GatherOrder::Phase::None;builds+=u->buildOrder.has_value() || u->construction.has_value();}bool developing=!ai.towns.empty() && session.runtime().threadCount() && (queues || builds);if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<(developing?"PASS":"FAIL")<<" source_ai file="<<ai.file<<" origin="<<ai.origin<<" towns="<<ai.towns.size()<<" orders="<<orders<<" queues="<<queues<<" gathering="<<gathering<<" builds="<<builds<<" threads="<<session.runtime().threadCount()<<" elapsed="<<session.simulationTime()<<" game_dll_loaded=false\n";if(!developing)throw std::runtime_error("AI did not reach a live town and paid development orders");return 0;}catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}}
